"use client";

import { useState, useEffect } from "react";
import { motion } from "framer-motion";
import { Home, Briefcase, Cpu, Music2, Terminal } from "lucide-react";

const NAV_ITEMS = [
    { id: "hero", icon: Home, label: "Home" },
    { id: "status", icon: Briefcase, label: "Status" },
    { id: "vault", icon: Cpu, label: "Vault" },
    { id: "frequency", icon: Music2, label: "Frequency" },
    { id: "terminal", icon: Terminal, label: "Terminal" },
];

export default function NavDock() {
    const [active, setActive] = useState("hero");

    useEffect(() => {
        const observers: IntersectionObserver[] = [];
        NAV_ITEMS.forEach(({ id }) => {
            const el = document.getElementById(id);
            if (!el) return;
            const obs = new IntersectionObserver(
                ([entry]) => {
                    if (entry.isIntersecting) setActive(id);
                },
                { threshold: 0.4 }
            );
            obs.observe(el);
            observers.push(obs);
        });
        return () => observers.forEach((o) => o.disconnect());
    }, []);

    const scrollTo = (id: string) => {
        const el = document.getElementById(id);
        el?.scrollIntoView({ behavior: "smooth" });
    };

    return (
        <motion.nav
            initial={{ y: 40, x: "-50%", opacity: 0 }}
            animate={{ y: 0, x: "-50%", opacity: 1 }}
            transition={{ delay: 1, type: "spring", stiffness: 200, damping: 25 }}
            className="fixed top-6 left-1/2 z-[9998] flex items-center gap-1 px-3 py-2 rounded-full"
            style={{
                background: "rgba(22,22,22,0.85)",
                backdropFilter: "blur(20px)",
                border: "0.5px solid rgba(255,255,255,0.1)",
                boxShadow: "0 8px 32px rgba(0,0,0,0.5), 0 0 0 0.5px rgba(255,255,255,0.05)",
            }}
        >
            {NAV_ITEMS.map(({ id, icon: Icon, label }) => {
                const isActive = active === id;
                return (
                    <button
                        key={id}
                        onClick={() => scrollTo(id)}
                        title={label}
                        aria-label={label}
                        className="relative group flex flex-col items-center justify-center w-10 h-10 rounded-full transition-colors duration-200"
                        style={{
                            background: isActive ? "rgba(255,77,0,0.12)" : "transparent",
                        }}
                    >
                        <Icon
                            size={18}
                            strokeWidth={1.25}
                            className="transition-colors duration-200"
                            style={{ color: isActive ? "#FF4D00" : "#A1A1AA" }}
                        />
                        {isActive && (
                            <motion.div
                                layoutId="nav-indicator"
                                className="absolute bottom-1 w-1 h-1 rounded-full bg-brand-orange"
                                transition={{ type: "spring", stiffness: 500, damping: 35 }}
                            />
                        )}
                    </button>
                );
            })}
        </motion.nav>
    );
}
